// Smooth Motion: generate frames for the display refresh rate or a fixed
// target. Frames are generated by the minterpolate video filter; the plugin
// publishes its readings as a page in Luma's native Stats panel.

let luma;
let active = false;
let original = {};
let lastTarget = 0;
let filterActive = false;
let statsPageError = "";
let appliedSignature = "";

function remember(key) {
    const value = luma.mpv.getProperty(key);
    if (value !== undefined && value !== null && value !== "")
        original[key] = value;
}

function restore(key) {
    if (original[key] !== undefined)
        luma.mpv.setProperty(key, original[key]);
}

function removeFilter() {
    // The old label is kept for users upgrading from an earlier plugin build.
    luma.mpv.command(["vf", "remove", "@luma-fps"]);
    luma.mpv.command(["vf", "remove", "@lumafps"]);
}

function configBool(key, fallback) {
    const value = luma.config.get(key, fallback);
    if (value === true || value === 1)
        return true;
    if (value === false || value === 0 || value === null || value === undefined)
        return false;
    const text = String(value).toLowerCase();
    return text === "true" || text === "1";
}

function displayFps(snapshot) {
    const mpvFps = Number(snapshot["display-fps"]);
    if (mpvFps > 1)
        return mpvFps;
    const screenFps = Number(snapshot["screen-refresh-rate"]);
    return screenFps > 1 ? screenFps : 0;
}

function targetFps(snapshot) {
    const mode = String(luma.config.get("mode", "display"));
    if (mode !== "display")
        return Math.max(1, Number(mode));
    const display = displayFps(snapshot);
    return display > 1 ? Math.round(display) : 60;
}

function formatFps(value) {
    const number = Number(value);
    return number > 0 ? number.toFixed(2) : "n/a";
}

function apply() {
    const state = luma.media.state();
    if (!state.hasVideo)
        return;

    if (!active) {
        remember("video-sync");
        remember("interpolation");
        remember("tscale");
        active = true;
    }

    const mode = String(luma.config.get("mode", "display"));
    const interpolate = configBool("interpolation", true);
    const quality = String(luma.config.get("quality", "mci"));
    const display = displayFps(luma.stats.snapshot());
    const targetFpsValue = mode === "display"
        ? (display > 1 ? Math.round(display) : 60)
        : Math.max(1, Number(mode));
    const signature = mode + ":" + targetFpsValue + ":" + (interpolate ? "1" : "0")
        + ":" + quality;
    if (!active || !filterActive || signature !== appliedSignature) {
        removeFilter();
        filterActive = false;
    } else {
        refreshStatsPage();
        return;
    }
    lastTarget = targetFpsValue;

    luma.mpv.setProperty("video-sync", mode === "display" ? "display-resample" : "audio");
    luma.mpv.setProperty("interpolation", "no");
    if (interpolate) {
        let filter = "@lumafps:minterpolate=fps=" + targetFpsValue
            + ":mi_mode=" + quality;
        if (quality === "mci")
            filter += ":mc_mode=aobmc:vsbmc=1";
        filterActive = luma.mpv.command(["vf", "add", filter]);
        if (!filterActive)
            luma.log.warn("minterpolate filter command was rejected");
    }
    appliedSignature = signature;

    refreshStatsPage();
}

function restoreAll() {
    if (!active)
        return;
    removeFilter();
    restore("video-sync");
    restore("interpolation");
    restore("tscale");
    active = false;
    filterActive = false;
    appliedSignature = "";
    original = {};
    lastTarget = 0;
    refreshStatsPage();
}

// display-fps can become available only after the first frames. Reapply once
// when the detected refresh rate changes; don't rebuild the filter every tick.
function checkDisplayFps() {
    if (!active || String(luma.config.get("mode", "display")) !== "display")
        return;
    const fps = Number(luma.mpv.getProperty("display-fps"));
    if (fps > 1 && Math.round(fps) !== lastTarget)
        apply();
}

function statsContent() {
    const snapshot = luma.stats.snapshot();
    const quality = String(luma.config.get("quality", "mci"));
    const source = Number(snapshot["container-fps"]);
    const output = Number(snapshot["estimated-vf-fps"]);
    const display = displayFps(snapshot);
    const target = targetFps(snapshot);
    const generated = filterActive ? target : output;

    return [
        { type: "label", text: luma.i18n.t("Source FPS") + ": " + formatFps(source) },
        { type: "label", text: luma.i18n.t("Output FPS") + ": " + formatFps(generated) },
        { type: "label", text: luma.i18n.t("MPV FPS estimate") + ": " + formatFps(output) },
        { type: "label", text: luma.i18n.t("Display FPS") + ": " + formatFps(display) },
        { type: "label", text: luma.i18n.t("Target FPS") + ": " + formatFps(target) },
        { type: "label", text: luma.i18n.t("Interpolation quality") + ": "
                       + luma.i18n.t(quality === "mci" ? "Smooth (MCI)" : "Fast (blend)") },
        { type: "separator" },
        { type: "label", text: luma.i18n.t("Motion interpolation") + ": "
                       + (configBool("interpolation", true)
                          ? luma.i18n.t("Enabled") : luma.i18n.t("Disabled")) },
        { type: "label", text: luma.i18n.t("Frame generation") + ": "
                       + (filterActive ? luma.i18n.t("Active") : luma.i18n.t("Inactive")) },
        { type: "label", text: luma.i18n.t("Filter") + ": "
                       + (filterActive ? "minterpolate" : luma.i18n.t("Inactive")) },
        { type: "label", text: luma.i18n.t("Mode") + ": "
                       + luma.i18n.t(String(luma.config.get("mode", "display"))) }
    ];
}

function refreshStatsPage() {
    if (!luma || !luma.stats)
        return;
    const result = luma.stats.setPage(
        "smooth", luma.i18n.t("Smooth Motion stats"), statsContent());
    if (result && result.ok === false) {
        if (statsPageError !== result.error) {
            statsPageError = result.error;
            luma.log.warn(result.error);
        }
        return;
    }
    statsPageError = "";
}

function activate(lumaApi) {
    luma = lumaApi;
    luma.log.info("Smooth Motion loaded");
    luma.events.on("startup", apply);
    luma.events.on("fileOpened", () => { refreshStatsPage(); });
    luma.events.on("mediaChanged", () => { refreshStatsPage(); });
    luma.events.on("settingsChanged", () => { apply(); refreshStatsPage(); });
    luma.events.on("positionChanged", () => {
        // fileOpened can arrive before mpv exposes a video track. Retry once
        // playback is actually advancing.
        const wantFrames = configBool("interpolation", true);
        const state = luma.media.state();
        if (!active) {
            // Let the first second of playback start before adding the heavy
            // filter, which otherwise causes a startup hitch.
            if (Number(state.position) >= 0.8)
                apply();
        } else if (wantFrames && !filterActive) {
            apply();
        } else {
            checkDisplayFps();
        }
        refreshStatsPage();
    });
    apply();
    refreshStatsPage();
}

function deactivate() {
    restoreAll();
}
